{
  "assessment": "The paper provides a detailed numerical study of spontaneous quantum turbulence in a 2D BEC formed via a thermal quench, with quantitative controls (quench time, temperature), readouts (vortex number, energy spectra, structure functions), and mechanisms (KZM scaling, Kolmogorov scaling). The evidence supports authoring an interactive experiment where the user varies quench time and observes the resulting vortex number and energy spectra.",
  "case_authoring_ready": true,
  "source": {
    "citation": "Seong-Ho Shinn et al., Spontaneous Quantum Turbulence in a Newborn Bose-Einstein Condensate via the Kibble-Zurek Mechanism, Physical Review Letters (2026), DOI:10.1103/b16v-hwp2",
    "journal_doi": "10.1103/b16v-hwp2",
    "arxiv_versioned_id": "2506.21670v3"
  },
  "paper_scope": "The paper uses numerical simulations of the 2D stochastic projected Gross-Pitaevskii equation to study the formation of a Bose-Einstein condensate via a thermal quench, focusing on the emergence of spontaneous quantum turbulence. It establishes Kibble-Zurek scaling of vortex number and equilibration time, Kolmogorov scaling of the incompressible kinetic energy spectrum, and universal collapse of spectra under KZ rescaling. The study is limited to a homogeneous 2D system with periodic boundary conditions, at low temperatures (T=1 and T=10^-6 in dimensionless units).",
  "mechanisms": [
    {
      "mechanism_id": "kibble_zurek_mechanism",
      "statement": "The Kibble-Zurek mechanism predicts universal scaling of defect density and freeze-out time in a finite-rate phase transition, based on the divergence of correlation length and relaxation time near the critical point.",
      "equations": [
        "xi = xi_0 / |epsilon|^nu",
        "tau = tau_0 / |epsilon|^{z*nu}",
        "hat_xi = xi_0 * (tau_Q / tau_0)^(nu/(1+z*nu))",
        "rho_v = (1/xi_0^2) * (tau_0 / tau_Q)^(2*nu/(1+z*nu))",
        "hat_t = (tau_0 * tau_Q^(z*nu))^(1/(1+z*nu))"
      ],
      "variable_names": [
        "xi",
        "tau",
        "hat_xi",
        "rho_v",
        "hat_t",
        "epsilon",
        "nu",
        "z",
        "tau_Q"
      ],
      "parameters": [
        {
          "name": "nu",
          "value": 0.5,
          "uncertainty": "source_unspecified",
          "unit": "dimensionless",
          "role": "correlation-length critical exponent (mean-field value)",
          "anchors": [
            {
              "line_start": 153,
              "line_end": 153,
              "support": "Using the mean-field values of the critical exponents nu = 1/2 and z = 2"
            }
          ]
        },
        {
          "name": "z",
          "value": 2,
          "uncertainty": "source_unspecified",
          "unit": "dimensionless",
          "role": "dynamic critical exponent (mean-field value)",
          "anchors": [
            {
              "line_start": 153,
              "line_end": 153,
              "support": "Using the mean-field values of the critical exponents nu = 1/2 and z = 2"
            }
          ]
        }
      ],
      "anchors": [
        {
          "line_start": 118,
          "line_end": 122,
          "support": "KZM uses divergence of correlation length xi = xi_0/|epsilon|^nu and relaxation time tau = tau_0/|epsilon|^{z*nu}; for linear quench epsilon = t/tau_Q, nonequilibrium correlation length hat_xi = xi_0 (tau_Q/tau_0)^(nu/(1+z*nu)); vortex density rho_v = (1/xi_0^2) (tau_0/tau_Q)^(2*nu/(1+z*nu))"
        },
        {
          "line_start": 123,
          "line_end": 123,
          "support": "Freeze-out timescale hat_t = (tau_0 * tau_Q^(z*nu))^(1/(1+z*nu))"
        }
      ]
    },
    {
      "mechanism_id": "kolmogorov_scaling",
      "statement": "In the inertial range, the incompressible kinetic energy spectrum follows a k^{-5/3} power law, derived from dimensional arguments assuming constant energy flux and negligible viscosity.",
      "equations": [
        "E_i(k) ~ k^{-5/3}"
      ],
      "variable_names": [
        "E_i",
        "k"
      ],
      "parameters": [],
      "anchors": [
        {
          "line_start": 200,
          "line_end": 204,
          "support": "With assumptions of constant energy flux and negligible viscosity, dimensional arguments imply k^{-5/3} scaling of incompressible kinetic energy spectrum"
        }
      ]
    },
    {
      "mechanism_id": "vortex_core_scaling",
      "statement": "At high momenta, the incompressible kinetic energy spectrum exhibits a k^{-3} power law reflecting the short-range structure of the vortex core, which is unrelated to turbulence.",
      "equations": [
        "E_i(k) ~ k^{-3}"
      ],
      "variable_names": [
        "E_i",
        "k"
      ],
      "parameters": [],
      "anchors": [
        {
          "line_start": 207,
          "line_end": 210,
          "support": "At higher momenta, the inertial range is interrupted by a second power law, E_i(k) ~ k^{-3}, reflecting short-range properties of the vortex core"
        }
      ]
    },
    {
      "mechanism_id": "kz_universality_of_spectrum",
      "statement": "The incompressible kinetic energy spectrum exhibits a universal collapse when rescaled by the KZ correlation length and energy scale, with the rescaling k -> k * tau_Q^(nu/(1+z*nu)) and E_i(k) -> E_i(k) * tau_Q^((1+nu)/(1+z*nu)).",
      "equations": [
        "E_i(k, tau_Q) = A(tau_Q) F(k * hat_xi)",
        "A(tau_Q) ~ tau_Q^{-(1+nu)/(1+z*nu)}",
        "k -> k * tau_Q^(nu/(1+z*nu))",
        "E_i(k) -> E_i(k) * tau_Q^((1+nu)/(1+z*nu))"
      ],
      "variable_names": [
        "E_i",
        "k",
        "tau_Q",
        "hat_xi",
        "nu",
        "z"
      ],
      "parameters": [],
      "anchors": [
        {
          "line_start": 314,
          "line_end": 323,
          "support": "Assuming scaling ansatz E_i(k, tau_Q) = A(tau_Q) F(k*hat_xi), using E_i ~ tau_Q^{-(1+2*nu)/(1+z*nu)} and hat_xi ~ tau_Q^{nu/(1+z*nu)} gives A(tau_Q) ~ tau_Q^{-(1+nu)/(1+z*nu)}, implying collapse under rescaling k -> k*tau_Q^{nu/(1+z*nu)} and E_i(k) -> E_i(k)*tau_Q^{(1+nu)/(1+z*nu)}"
        }
      ]
    },
    {
      "mechanism_id": "compressible_energy_scaling",
      "statement": "At low temperature, the compressible kinetic energy is dominated by phonons emitted during vortex-antivortex annihilation, leading to a scaling E_c ~ tau_Q^{-1} and a spectral collapse under the same rescaling as the incompressible spectrum.",
      "equations": [
        "E_p^tot ~ tau_Q^{-(3*nu + 1/2)/(1+z*nu)}",
        "E_p(k) ~ tau_Q^{-(2*nu + 1/2)/(1+z*nu)} * G(k * tau_Q^{nu/(1+z*nu)})"
      ],
